// Parse the AI response and fall back to original metadata if AI fails
const original = $('Prepare Video Data').first().json;
let aiData = null;
try {
  const aiResponse = $('AI: Enrich Metadata').first().json;
  const content = aiResponse?.choices?.[0]?.message?.content;
  if (content) {
    const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();
    aiData = JSON.parse(cleaned);
  }
} catch (e) { console.log('[project003] AI parse failed: ' + e.message); }
const result = {
  // routing IDs (passthrough)
  job_id:         original.job_id,
  destination_id: original.destination_id,
  pipeline_id:    original.pipeline_id,
  video_id:       original.video_id,
  // enriched
  youtube_title:       (aiData?.youtube_title       || original.title).substring(0, 100),
  youtube_description:  aiData?.youtube_description || original.description,
  youtube_tags:         aiData?.youtube_tags        || [],
  // original passthrough
  title:        original.title,
  file_path:    original.file_path,
  source_url:   original.source_url,
  channel_name: original.channel_name,
  channel_id:   original.channel_id,
  channel_url:  original.channel_url,
  duration:     original.duration,
  timestamp:    original.timestamp,
  ai_used:      !!aiData,
};
console.log('[project003] AI: ' + (aiData ? 'SUCCESS' : 'FALLBACK') + ' — ' + result.youtube_title);
return [{ json: result }];

const meta = $('AI: Parse & Fallback').first().json;

// Read YouTube upload result (continueOnFail means errors come through as data)
let ytResult = { status: 'skipped' };
try {
  const ytData = $('YouTube Upload').first().json;
  if (ytData && ytData.id) {
    ytResult = {
      status:   'success',
      video_id: ytData.id,
      url:      'https://youtube.com/watch?v=' + ytData.id,
    };
  } else if (ytData && ytData.error) {
    ytResult = { status: 'error', error: ytData.error.message || JSON.stringify(ytData.error) };
  } else {
    ytResult = { status: 'error', error: 'Unexpected response: ' + JSON.stringify(ytData) };
  }
} catch (e) {
  ytResult = { status: 'error', error: e.message };
}

const summary = {
  title:     meta.title,
  channel:   meta.channel_name,
  source:    meta.source_url,
  processed: new Date().toISOString(),
  uploads:   { youtube: ytResult },
};

const icon = ytResult.status === 'success' ? '[OK]' : '[FAIL]';
console.log('[project003] ' + icon + ' ' + meta.title + ' -> YouTube: ' + ytResult.status);
if (ytResult.url) console.log('[project003] Published: ' + ytResult.url);

return [{ json: summary }];
